async refresh(presented: string) {
  // BUG 1: lookup by RAW token — the DB stores raw refresh tokens in plaintext
  const record = await this.familyRepo.findOne({ where: { token: presented } });
  if (!record || record.revoked) throw new UnauthorizedException();

  // BUG 2: no rotation, no reuse check — the same token is reissued and stays valid
  const accessToken = await this.tokens.signAccess(record.userId);
  return { accessToken, refreshToken: presented };
}

