async refresh(presented: string) {
  const record = await this.familyRepo.findOne({
    where: { tokenHash: this.hash(presented) },   // FIX: look up by HASH, never raw
  });
  if (!record || record.revoked) throw new UnauthorizedException();

  if (record.consumed) {                          // FIX: reuse detection
    await this.revokeFamily(record.familyId);      // a single-use token came back → kill the family
    throw new UnauthorizedException('token reuse detected');
  }

  await this.markConsumed(record.id);              // FIX: old token is now spent (single-use)
  const refreshToken = await this.tokens.signRefresh(record.userId, record.familyId);
  await this.familyRepo.save({                     // FIX: store the HASH of the NEW token
    familyId: record.familyId,
    userId: record.userId,
    tokenHash: this.hash(refreshToken),
    consumed: false,
    revoked: false,
  });
  const accessToken = await this.tokens.signAccess(record.userId);
  return { accessToken, refreshToken };            // a brand-new refresh token, rotated
}

Why: (1) lookup and storage are by hash, so a DB leak yields no usable tokens. (2) Rotation mints a new refresh token and marks the old one consumed, shrinking a leaked token's validity to one refresh cycle. (3) A consumed token presented again trips reuse detection and revokes the whole family. The endpoint should also set the new refresh token as an httpOnly, Secure, SameSite cookie rather than returning it in the JSON body.

